      SUBROUTINE LATSTOR      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'LOUTAR.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DBEAMR.CIN'      INCLUDE 'DSPECR.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM11.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LBLSVE.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OUTNEWC.CIN'      INCLUDE 'OUTNEWR.CIN'      INCLUDE 'YAW.CIN'C----------------------------------------------------------------------      LOGICAL ATWELCC\\\\\\\\\\\\\\\\ ADDITIONS 11/26/97 \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C\\\\\\\\\\\\\\\\ ADDED 11/25/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C\\\\\\\\\\\\\\\\\\\ ADDED 12/1/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\	IF ((TYPE .EQ. 10) .AND. (LABEL(NUM) .EQ. LABELSVE)) THEN		ATWEL = .TRUE.		LABELSVE = ' '	ELSE		ATWEL = ATWE	END IFC\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\ 12/1/97 \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\	IF (.NOT. ATWEL) GO TO 5220C\\\\\\\\\\\\\\ ADDED 12/15/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	WILL INCREMENT ICOUNT AT 5 200. IF TYPE IS NOT ONE OF THE SELECTEDC	TYPES ICOUNT WILL BE DECREMENTED.	ICOUNT = ICOUNT + 1C\\\\\\\\\\\\\\\\\\\\\ 12/17/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	NEED TO ZERO OUTNEWC        DO IA = 1, LOUTAR          OUTNEW(IA,ICOUNT) = 0.0        END DO        OUTLAB (ICOUNT) = 'NOT DEFINED.'        OUTNEWL(ICOUNT) = .FALSE.C\\\\\\\\\\\\\\\\\\\\ 12/17/97 \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C\\\\\\\\\\\\\\\\\ 12/15/97 \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\CC     BEAMC      IF (TYPE .EQ. 1) THEN        DO IB = 1, 18          J = IPTOJ(IB)          IF (J .GT. 0) THEN            DBEAM_VAL(IB) = DATAR(I+J)          ENDIF        ENDDOC        DO IB = 10, 15          J = IPTOJ(IB)          IF (J .NE. 0) GO TO 5210        END DOC        DO IB = 1, 4          J = IPTOJ(IB)          IF (J .EQ. 0) GO TO 5210          IF (DBEAM_VAL(IB) .EQ. 0.0) GO TO 5210        END DOC        SIG11 = DBEAM_VAL(1)**2        SIG22 = DBEAM_VAL(2)**2        SIG33 = DBEAM_VAL(3)**2        SIG44 = DBEAM_VAL(4)**2        EPSX = SQRT(SIG11*SIG22)        BETAX = SQRT(SIG11/SIG22)        ALPHAX = 0.0        EPSY = SQRT(SIG33*SIG44)        BETAY = SQRT(SIG33/SIG44)        ALPHAY = 0.0        DBEAM_VAL(10) = BETAX        DBEAM_VAL(11) = ALPHAX        DBEAM_VAL(12) = EPSX        DBEAM_VAL(13) = BETAY        DBEAM_VAL(14) = ALPHAY        DBEAM_VAL(15) = EPSYC        GO TO 5 210      ENDIFCC       DRIFTC        IF (TYPE .EQ. 3) THEN          L = DATAR(I+1)*UNITI(8)          OUTNEW(1,ICOUNT) = L          GO TO 5 210	END IFCC	BENDC        IF (TYPE .EQ. 4) THEN          IL = IPTOJ( 1) + I          OUTNEW(1,ICOUNT) = DATAR(IL)          IANG = IPTOJ( 4) + I          OUTNEW(2,ICOUNT) = DATAR(IANG)          IN  = IPTOJ( 5)          IK1 = IPTOJ( 6)          NB  = 0.0          K1  = 0.0          IF (IK1 .EQ. 0) THEN            IF (IN .NE. 0) THEN              NB = DATAR(I + IN)            END IF          ELSE            IF (IK1 .NE. 0.0) THEN              K1 = DATAR(I + IK1)            END IF            K1 = K1/UNITI(8)**2            IF (H0 .NE. 0.0) NB = -K1/H0**2          END IF          OUTNEW(3,ICOUNT) = K1          IS = IPTOJ(13)          IF (IS .GT. 0) THEN            OUTNEW(4,ICOUNT) = DATAR(I + IS)          END IF          IO = IPTOJ(17)          IF (IO .GT. 0) THEN            OUTNEW(5,ICOUNT) = DATAR(I + IO)          END IF          IT = IPTOJ(18)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(I + IT)          END IF          GO TO 5 210	END IFCC	QUADRUPOLESC        IF (TYPE .EQ. 5) THEN          IL = IPTOJ( 1) + I          L = DATAR(IL)*UNITI(8)          OUTNEW(1,ICOUNT) = LC          IB = IPTOJ(2)          IAP = IPTOJ(3)          IG = IPTOJ(4)          IK1 = IPTOJ(5)          K1  = 0.0          IF (IB .NE. 0 .AND. IAP .NE. 0) THEN            B = DATAR(I+IB)*UNITI(9)            AP = DATAR(I+IAP)*UNITI(1)            K1 = B/(AP*RI)          ENDIF          IF (IG .NE. 0) THEN            GRAD = DATAR(I+IG)*UNITI(9)/UNITI(1)            K1 = GRAD/RI          ENDIF          IF (IK1 .NE. 0) THEN            K1 = DATAR(I + IK1)*UNITI(8)**2          END IF          K1 = K1/UNITI(8)**2          OUTNEW(3,ICOUNT) = K1          IT = IPTOJ(7)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(I + IT)          END IF          GO TO 5 210	END IFCC	FITC        IF (TYPE .EQ. 10) THEN          GO TO 5 210        END IFCC       ACCELERATIONC        IF (TYPE .EQ. 11) THEN          IADR = I + 1          L = DATAR(IADR)*UNITI(8)          OUTNEW(1,ICOUNT) = LC          IADR = I + 2          EGAIN = DATAR(IADR)*UNITI(11)          OUTNEW(2,ICOUNT) = EGAINC          IADR = I + 3          PHASEL = DATAR(IADR)/RADIAN          OUTNEW(3,ICOUNT) = PHASELC          IADR = I + 4          IF (IPTOJ(5) .EQ. 0) THEN            WAVEL = DATAR(IADR)*UNITI(5)            FREQ = CLIGHT*1.0E-6/WAVEL          ELSE            FREQ = DATAR(IADR)            WAVEL = CLIGHT*1.0E-6/FREQ          ENDIF          OUTNEW(4,ICOUNT) = FREQ          GO TO 5 210        ENDIFCC       BEAM CORRELATIONSC        IF (TYPE .EQ. 12) THEN          IF (LTWISS) THEN            SIG11 = DBEAM_VAL(1)**2            SIG22 = DBEAM_VAL(2)**2            SIG33 = DBEAM_VAL(3)**2            SIG44 = DBEAM_VAL(4)**2C             R21 = 0.0            IR21 = IPTOJ(1)            IF (IR21 .NE. 0.0) THEN              R21 = DATAR(I+IR21)            ENDIF            SIG21 = R21*SQRT(SIG11*SIG22)C            R43 = 0.0            IR43 = IPTOJ(6)            IF (IR43 .NE. 0.0) THEN              R43 = DATAR(I+IR43)            ENDIF            SIG43 = R43*SQRT(SIG33*SIG44)C            EPSX = SQRT(SIG11*SIG22 - SIG21**2)            BETAX = SIG11/EPSX            ALPHAX = - SIG21/EPSX            EPSY = SQRT(SIG33*SIG44 - SIG43**2)            BETAY = SIG33/EPSY            ALPHAY = - SIG43/EPSYC              DBEAM_VAL(10) = BETAX            DBEAM_VAL(11) = ALPHAX            DBEAM_VAL(12) = EPSX            DBEAM_VAL(13) = BETAY            DBEAM_VAL(14) = ALPHAY            DBEAM_VAL(15) = EPSYC            GO TO 5 210          ELSE            DO IB = 1, 15            J = IPTOJ(IB)            DCORR_VAL(IB) = 0.0            IF (J .GT. 0) THEN              DCORR_VAL(IB) = DATAR(I+J)            ENDIF            END DO          ENDIF        ENDIFCC       SPECIAL PARAMETERSC        IF (TYPE .EQ. 16) THEN          J = INT(DATAR(I+1))          DSPEC_VAL(J+3) = PARAM          GO TO 5 210        ENDIFCC	SEXTUPOLESC        IF (TYPE .EQ. 18) THEN          IL = IPTOJ(1) + I          L = DATAR(IL)*UNITI(8)          OUTNEW(1,ICOUNT) = LC          IB = IPTOJ(2)          IAP = IPTOJ(3)          IF (IB .GT. 0 .AND. IAP .GT. 0) THEN            B = DATAR(I+IB)*UNITI(9)*RI/PREF            AP = DATAR(I+IAP)*UNITI(1)            K2 = B/(RI*AP**2)            K2 = K2*UNITI(8)**3            OUTNEW(4,ICOUNT) = K2          ENDIFC          IS = IPTOJ(4)          IF (IS .GT. 0) THEN            OUTNEW(4,ICOUNT) = DATAR(IS + I)          END IFC          IT = IPTOJ(5)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(IT + I)          END IF          GO TO 5 210	END IFCC       SOLENOIDSC        IF (TYPE .EQ. 19) THEN          IADR = I + 1          L = DATAR(IADR)          L = L*UNITI(8)          OUTNEW(1,ICOUNT) = LC          IB = IPTOJ(2)          IK = IPTOJ(3)          IF (IB .NE. 0) THEN            IADR = I + IB            B = DATAR(IADR)            B = B*UNITI(9)*RI/PREF            KO = DEN(B/RI)            KL = 0.5*KO*L            OUTNEW(2,ICOUNT) = KL          ENDIFC          IF (IK .NE. 0) THEN            IADR = I + IK            KL = DATAR(IADR)            KL = KL*UNITI(13)            OUTNEW(2,ICOUNT) = KL          ENDIF          GO TO 5 210        ENDIFCC       SROTC        IF (TYPE .EQ. 20) THEN          IADR = I + 1          ANGLE = DATAR(IADR)*UNITI(13)          OUTNEW(1,ICOUNT) = ANGLE          GO TO 5 210        ENDIFCC	OCTUPOLESC        IF (TYPE .EQ. 25) THEN          IL = IPTOJ(1) + I          L = DATAR(IL)*UNITI(8)          OUTNEW(1,ICOUNT) = LC          IB = IPTOJ(2)          IAP = IPTOJ(3)          IF (IB .GT. 0 .AND. IAP .GT. 0) THEN            B = DATAR(I+IB)*UNITI(9)*RI/PREF            AP = DATAR(I+IAP)*UNITI(1)            K3 = B/(RI*AP**3)            K3 = K3*UNITI(8)**4            OUTNEW(5,ICOUNT) = K3          ENDIFC          IO = IPTOJ(4)	  IF (IO .GT. 0) THEN            OUTNEW(5,ICOUNT) = DATAR(IO + I)          END IFC          IT = IPTOJ(5)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(IT + I)          END IF          GO TO 5 210	END IFCC       ETA FUNCTIONC        IF (TYPE .EQ. 27) THEN          DO J = 1, 6            DETA_VAL(J) = ETA(J)          ENDDO          GO TO 5210        ENDIFCC	SBEND OR RBENDC        IF ((TYPE .EQ. 28) .OR. (TYPE .EQ. 29)) THEN          IL = IPTOJ( 1)          IB = IPTOJ( 2)          IRAD = IPTOJ( 3)          IANG = IPTOJ( 4)C          IF (IL .NE. 0 .AND. IB .NE. 0) THEN            L = DATAR(I+IL)            B = DATAR(I+IB)            L = DATAR(I+IL)*UNITI(8)            B = DATAR(I+IB)*UNITI(9)*RI/PREF            H0 = B/RI            RAD = 0.0            IF (TYPE .EQ. 28 .AND. H0 .NE. 0.0) THEN              ANGLE = 2.0*ASIN(0.5*H0*L)            ELSE              ANGLE = H0*L            ENDIF          ENDIFC          IF (IL .NE. 0 .AND. IANG .NE. 0) THEN            L = DATAR(I+IL)*UNITI(8)            ANGLE = DATAR(I+IANG)*UNITI(7)          ENDIFC          IF (IL .NE. 0 .AND. IRAD .NE. 0) THEN            L = DATAR(I+IL)*UNITI(8)            RAD = DATAR(I+IRAD)*UNITI(8)            H0 = 1.0/RAD            IF (TYPE .EQ. 28) THEN              ANGLE = 2.0*ASIN(0.5*L/RAD)            ELSE              ANGLE = L/RAD            ENDIF          ENDIFC          IF (IRAD .NE. 0 .AND. IANG .NE. 0) THEN            RAD = DATAR(I+IRAD)*UNITI(8)            ANGLE = DATAR(I+IANG)*UNITI(7)            IF (TYPE .EQ. 28) THEN              L = 2.0*RAD*SIN(0.5*ANGLE)            ELSE              L = RAD*ANGLE            ENDIF          ENDIFC          IF (IB .NE. 0 .AND. IANG .NE. 0) THEN            B = DATAR(I+IB)*UNITI(9)*RI/PREF            ANGLE = DATAR(I+IANG)*UNITI(7)            H0 = B/RI            IF (TYPE .EQ. 28) THEN              L = 2.0*RAD*SIN(0.5*ANGLE)            ELSE              L = RAD*ANGLE            ENDIF          ENDIFC          OUTNEW(1,ICOUNT) = L           OUTNEW(2,ICOUNT) = ANGLEC          IN  = IPTOJ( 5)          IK1 = IPTOJ( 6)          NB  = 0.0          K1  = 0.0          IF (IK1 .EQ. 0) THEN            IF (IN .NE. 0) THEN              NB = DATAR(I + IN)              K1 = - NB*H0**2            END IF          ELSE            IF (IK1 .NE. 0.0) THEN              K1 = DATAR(I + IK1)*UNITI(8)**2            END IF            K1 = K1/UNITI(8)**2            IF (H0 .NE. 0.0) NB = - K1/H0**2          END IF          OUTNEW(3,ICOUNT) = K1C          IK2 = IPTOJ(15)          IF (IK2 .GT. 0) THEN            OUTNEW(4,ICOUNT) = DATAR(I + IK2)          END IFC          IK3 = IPTOJ(21)          IF (IK3 .GT. 0) THEN            OUTNEW(5,ICOUNT) = DATAR(I + IK3)          END IFC          IT = IPTOJ(24)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(I + IT)          END IF	  GO TO 5 210	END IFCC	MARKERC	IF (TYPE .EQ. 31) THEN		GO TO 5 210	END IFCC	HKICK AND VKICKC        IF ((TYPE .EQ. 35) .OR. (TYPE .EQ. 36)) THEN          IL = IPTOJ(1)          IF (IL .GT. 0) THEN            L = DATAR(I+IL)*UNITI(8)            OUTNEW(1,ICOUNT) = L          END IFC          IB = IPTOJ(2)          IF (IB .GT. 0) THEN            B = DATAR(I+IB)            B = B*UNITI(9)*RI/PREF            H0 = B/RI            ANGLE = H0*L            OUTNEW(2,ICOUNT) = - ANGLE          ENDIFC          IK = IPTOJ(4)          IF (IK .GT. 0) THEN            OUTNEW(2,ICOUNT) = DATAR(I+IK)*UNITI(7)          END IFC          IANG = IPTOJ(3)          IF (IANG .GT. 0) THEN            OUTNEW(2,ICOUNT) = - DATAR(I + IANG)*UNITI(7)          END IFC          IT = IPTOJ(5)          IF (IT .GT. 0) THEN            OUTNEW(6,ICOUNT) = DATAR(I + IT)          END IF          GO TO 5 210	END IFCC       KICKERC        IF (TYPE .EQ. 42) THEN          IL = IPTOJ(1)          IF (IL .GT. 0) THEN            L = DATAR(I+IL)*UNITI(8)            OUTNEW(1,ICOUNT) = L          END IFCC          IHK = IPTOJ(2)          IF (IHK .GT. 0) THEN            OUTNEW(2,ICOUNT) = DATAR(I+IHK)*UNITI(7)          END IFC          IVK = IPTOJ(3)          IF (IVK .GT. 0) THEN            OUTNEW(3,ICOUNT) = DATAR(I+IVK)*UNITI(7)          END IF          GO TO 5 210        ENDIFCC\\\\\\\\\\\\\\ ADDED 12/15/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	WILL INCREMENT ICOUNT NEAR 5 200. IF WE COME HERE WILL DECREMENTC	ICOUNT.	ICOUNT = ICOUNT - 1C\\\\\\\\\\\\\\\\\\\\\\\\\\ 12/15/97 \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\	GO TO 5 220 5210	CONTINUEC\\\\\\\\\\\\ LATTICE FUNCTIONS. \\\\\\\\\\\\\\	OUTNEW( 7,ICOUNT) = ALPHAX	OUTNEW( 8,ICOUNT) = BETAX	OUTNEW( 9,ICOUNT) = PSIX/UNITO(12)	OUTNEW(10,ICOUNT) = ETA(1)	OUTNEW(11,ICOUNT) = ETA(2)	OUTNEW(12,ICOUNT) = ALPHAY	OUTNEW(13,ICOUNT) = BETAY	OUTNEW(14,ICOUNT) = PSIY/UNITO(12)	OUTNEW(15,ICOUNT) = ETA(3)	OUTNEW(16,ICOUNT) = ETA(4)C\\\\\\\\\\\\\ SPACE COORDINATES. \\\\\\\\\\\\	OUTNEW(21,ICOUNT) = LC	OUTNEW(22,ICOUNT) = X0(4,1)/UFLOOR(1)	OUTNEW(23,ICOUNT) = X0(4,2)/UFLOOR(1)	OUTNEW(24,ICOUNT) = X0(4,3)/UFLOOR(1)	OUTNEW(25,ICOUNT) = YAW	OUTNEW(26,ICOUNT) = PITCH	OUTNEW(27,ICOUNT) = ROLLC\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C\\\\\\\\\\\\\\\\\ 12/15/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	SQUARE ROOT OF SIGMA MATRIX        NSI = 28        DO ISI = 1, 6          DO JSI = ISI, 6            OUTNEW(NSI,ICOUNT) = SIT(ISI,JSI)            NSI = NSI + 1          END DO	END DOC\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C\\\\\\\\\\\\\\\ ADDED 12/16/97 NMG \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	CENTROIDC        DO I1 =1, 4          OUTNEW(I1 + 16,ICOUNT) = CEN(I1)	END DOC\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\	OUTLAB (ICOUNT) = LABEL(NUM)	IOUTTYP(ICOUNT) = TYPE	OUTNEWL(ICOUNT) = .TRUE. 5220	CONTINUEC\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\C	WRITE (23,*) NUM, LABEL(NUM), TYPE, ICOUNT, OUTNEWL(ICOUNT)      RETURN      END